package com.example.starter.restitution.error;

/**
 * 业务可预期错误，携带 HTTP 状态码与可选的结构化错误体。
 */
public class ApiException extends RuntimeException {

    private final int status;
    private final String code;
    private final transient Object details;

    public ApiException(int status, String code, String message) {
        this(status, code, message, null);
    }

    public ApiException(int status, String code, String message, Object details) {
        super(message);
        this.status = status;
        this.code = code;
        this.details = details;
    }

    public static ApiException badRequest(String message) {
        return new ApiException(400, "bad_request", message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(404, "not_found", message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(409, code, message);
    }

    public static ApiException forbidden(String message) {
        return new ApiException(403, "forbidden", message);
    }

    public static ApiException unprocessable(String message, Object details) {
        return new ApiException(422, "unprocessable_decision", message, details);
    }

    public int getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public Object getDetails() {
        return details;
    }
}

package com.example.starter.restitution.error;

/**
 * 幂等重放：不是错误，携带首次成功的状态码与响应体，由控制器建议原样返回。
 */
public class IdempotentReplayException extends RuntimeException {

    private final int httpStatus;
    private final String responseBody;

    public IdempotentReplayException(int httpStatus, String responseBody) {
        super("idempotent replay");
        this.httpStatus = httpStatus;
        this.responseBody = responseBody;
    }

    public int getHttpStatus() {
        return httpStatus;
    }

    public String getResponseBody() {
        return responseBody;
    }
}

package com.example.starter.restitution.web.dto;

import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 创建案件请求：1至10个案内唯一、非空藏品编号。
 */
public record CreateCaseRequest(
        @NotEmpty(message = "藏品编号列表不能为空")
        @Size(max = 10, message = "藏品编号至多10个")
        List<String> artifactNos
) {
}

package com.example.starter.restitution.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 登记主张请求：案内唯一 claimKey、申请人、非空说明、非空藏品子集。
 */
public record RegisterClaimRequest(
        @NotBlank(message = "claimKey 不能为空")
        @Size(max = 64)
        String claimKey,
        @NotBlank(message = "申请人不能为空")
        @Size(max = 128)
        String applicant,
        @NotBlank(message = "主张说明不能为空")
        @Size(max = 4000)
        String statement,
        @NotEmpty(message = "主张藏品子集不能为空")
        @Size(max = 10, message = "主张藏品至多10个")
        List<String> artifactNos
) {
}

package com.example.starter.restitution.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 追加证据请求：evidenceKey 案内唯一，summary 非空，证据只存摘要。
 */
public record AddEvidenceRequest(
        @NotBlank(message = "evidenceKey 不能为空")
        @Size(max = 64)
        String evidenceKey,
        @NotBlank(message = "证据摘要不能为空")
        @Size(max = 4000)
        String summary
) {
}

package com.example.starter.restitution.web.dto;

import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 裁决提交请求：expectedVersion 为提交方依据的案件版本，claimKeys 为1至10个不同主张编号。
 */
public record DecideRequest(
        @NotNull(message = "expectedVersion 不能为空")
        Long expectedVersion,
        @NotEmpty(message = "至少选定一个主张")
        @Size(max = 10, message = "至多选定10个主张")
        List<String> claimKeys
) {
}

