package com.example.starter.restitution.web.dto;

import java.util.List;

/**
 * 案件视图：含案件编号、状态、当前版本与藏品清单。
 */
public record CaseResponse(
        String caseKey,
        String status,
        long version,
        List<String> artifactNos
) {
}

package com.example.starter.restitution.web.dto;

import java.util.List;

/**
 * 主张视图：含状态、证据版本、藏品子集与当前版本批准的评审人集合。
 */
public record ClaimResponse(
        String claimKey,
        String applicant,
        String statement,
        String status,
        long evidenceVersion,
        List<String> artifactNos,
        List<String> currentApprovers
) {
}

package com.example.starter.restitution.web.dto;

/**
 * 证据视图：撤销历史保留，status 表示当前是否有效。
 */
public record EvidenceResponse(
        String evidenceKey,
        String summary,
        String status,
        long evidenceVersion
) {
}

package com.example.starter.restitution.web.dto;

import java.util.List;

/**
 * 裁决结果视图：终态案件版本、选定主张、藏品到申请人冻结关系、有效证据与批准快照。
 */
public record DecisionResponse(
        String caseKey,
        String status,
        long version,
        List<FrozenClaimView> claims,
        List<FrozenArtifactView> artifacts,
        List<FrozenEvidenceView> evidence,
        List<FrozenApprovalView> approvals
) {
}

package com.example.starter.restitution.web.dto;

/**
 * 冻结主张快照视图。
 */
public record FrozenClaimView(
        String claimKey,
        String applicant,
        String statement
) {
}

package com.example.starter.restitution.web.dto;

/**
 * 藏品冻结关系视图：藏品编号 -> 判给的主张与申请人。
 */
public record FrozenArtifactView(
        String artifactNo,
        String claimKey,
        String applicant
) {
}

package com.example.starter.restitution.web.dto;

/**
 * 冻结有效证据快照视图。
 */
public record FrozenEvidenceView(
        String claimKey,
        String evidenceKey,
        String summary,
        long evidenceVersion
) {
}

package com.example.starter.restitution.web.dto;

/**
 * 冻结批准信息快照视图。
 */
public record FrozenApprovalView(
        String claimKey,
        String reviewer,
        long evidenceVersion
) {
}

