    public void bumpVersion(long caseId) {
        int updated = jdbc.update(
                "update restitution_case set version = version + 1 where id = ?", caseId);
        if (updated != 1) {
            throw new IllegalStateException("案件版本递增失败: " + caseId);
        }
    }

