        CaseRow caseRow = lockOpenCase(caseKey);
        EvidenceRow evidence = evidenceRepository.lockByKey(caseRow.id(), evidenceKey);
        if (evidence == null) {
            throw ApiException.notFound("证据不存在: " + evidenceKey);
