242	    public void approve(String actorId, String requestId, String caseKey, String claimKey) {
243	        requireText(claimKey, "claimKey");
244	        String fingerprint = fingerprint(Map.of("caseKey", caseKey, "claimKey", claimKey));
245	        withIdempotency(requestId, actorId, "approve", fingerprint, 204, () -> {
246	            CaseRow caseRow = lockOpenCase(caseKey);
247	            ClaimRow claim = claimRepository.lockByKey(caseRow.id(), claimKey);
248	            if (claim == null) {
249	                throw ApiException.notFound("主张不存在: " + claimKey);
250	            }
251	            ensureClaimNotWithdrawn(claim);
252	            if (actorId.equals(claim.applicant())) {
253	                throw ApiException.forbidden("评审人不能是主张申请人，禁止自批");
254	            }
255	            if (evidenceRepository.countActiveForClaim(claim.id()) < 1) {
256	                throw ApiException.unprocessable("至少存在一份有效证据才可批准",
257	                        Map.of("claimKey", claimKey, "missing", List.of("valid_evidence")));
258	            }
259	            long version = claim.evidenceVersion();
260	            List<String> currentReviewers = approvalRepository.findReviewersAtVersion(claim.id(), version);
261	            if (currentReviewers.contains(actorId)) {
262	                // 同一人同版本不重复计数，也不再次推案件版本。
263	                return null;
264	            }
265	            boolean firstApprovalAtVersion = currentReviewers.isEmpty();
266	            try {
267	                approvalRepository.insert(caseRow.id(), claim.id(), actorId, version);
268	            } catch (DuplicateKeyException e) {
269	                // 并发下同人同版本：不重复计数，静默成功。
270	                return null;
271	            }
272	            // 仅该证据版本的首次批准推案件版本；同人同版本不重复计数。
273	            if (firstApprovalAtVersion) {
274	                caseRepository.bumpVersion(caseRow.id());
275	            }
276	            return null;
277	        });
278	    }
