280	    @Transactional
281	    public DecisionResponse decide(String actorId, String requestId, String caseKey, DecideRequest req) {
282	        List<String> selectedKeys = normalizeSelectedClaimKeys(req.claimKeys());
283	        if (req.expectedVersion() == null || req.expectedVersion() <= 0) {
284	            throw ApiException.badRequest("expectedVersion 必须为正整数");
285	        }
286	        long expectedVersion = req.expectedVersion();
287	        String fingerprint = fingerprint(java.util.Map.ofEntries(
288	                java.util.Map.entry("caseKey", caseKey),
289	                java.util.Map.entry("expectedVersion", expectedVersion),
290	                java.util.Map.entry("claimKeys", sortedCopy(selectedKeys))));
291	        return withIdempotency(requestId, actorId, "decide", fingerprint, 201, () -> {
292	            CaseRow caseRow = lockOpenCase(caseKey);
293	            // 版本竞争优先按 409 裁决：证据撤销/主张撤回/另一裁决都会推高版本或落终态。
294	            if (caseRow.version() != expectedVersion) {
295	                throw ApiException.conflict("version_conflict",
296	                        "案件版本冲突: expected=" + expectedVersion + ", actual=" + caseRow.version());
297	            }
298	
299	            List<String> caseArtifacts = caseRepository.findArtifactNos(caseRow.id());
300	            List<ClaimRow> selectedClaims = claimRepository.lockByKeys(caseRow.id(), selectedKeys);
301	            Map<String, ClaimRow> claimByKey = new LinkedHashMap<>();
302	            for (ClaimRow claim : selectedClaims) {
303	                claimByKey.put(claim.claimKey(), claim);
304	            }
305	
306	            // 逐主张收集缺项：不存在 / 已撤回 / 当前版本批准不足两名不同评审人。
307	            Map<String, List<String>> claimDeficiencies = new LinkedHashMap<>();
308	            Map<String, List<String>> claimReviewers = new LinkedHashMap<>();
309	            for (String key : selectedKeys) {
310	                ClaimRow claim = claimByKey.get(key);
311	                List<String> missing = new ArrayList<>();
312	                if (claim == null) {
313	                    missing.add("claim_not_found");
314	                    claimDeficiencies.put(key, missing);
315	                    continue;
316	                }
317	                if (com.example.starter.restitution.domain.ClaimStatus.WITHDRAWN.name().equals(claim.status())) {
318	                    missing.add("withdrawn");
319	                }
320	                List<String> reviewers = approvalRepository.findReviewersAtVersion(
321	                        claim.id(), claim.evidenceVersion());
322	                claimReviewers.put(key, reviewers);
323	                if (reviewers.size() < REQUIRED_APPROVERS) {
324	                    missing.add("current_approval");
325	                }
326	                if (!missing.isEmpty()) {
327	                    claimDeficiencies.put(key, missing);
328	                }
329	            }
330	
331	            // 藏品覆盖：仅统计存在且未撤回主张的覆盖范围；重复/缺失分别收集。
332	            Map<String, List<String>> coveredBy = new LinkedHashMap<>();
333	            for (String no : caseArtifacts) {
334	                coveredBy.put(no, new ArrayList<>());
335	            }
336	            for (String key : selectedKeys) {
337	                ClaimRow claim = claimByKey.get(key);
338	                if (claim == null
339	                        || com.example.starter.restitution.domain.ClaimStatus.WITHDRAWN.name().equals(claim.status())) {
340	                    continue;
341	                }
342	                for (String no : claimRepository.findClaimArtifactNos(claim.id())) {
343	                    coveredBy.computeIfAbsent(no, k -> new ArrayList<>()).add(key);
344	                }
345	            }
346	            List<String> duplicateArtifacts = new ArrayList<>();
347	            List<String> missingArtifacts = new ArrayList<>();
348	            for (String no : caseArtifacts) {
349	                List<String> owners = coveredBy.getOrDefault(no, List.of());
350	                if (owners.isEmpty()) {
351	                    missingArtifacts.add(no);
352	                } else if (owners.size() > 1) {
353	                    duplicateArtifacts.add(no);
354	                }
355	            }
356	
357	            if (!claimDeficiencies.isEmpty() || !duplicateArtifacts.isEmpty() || !missingArtifacts.isEmpty()) {
358	                Map<String, Object> details = new LinkedHashMap<>();
359	                details.put("claimDeficiencies", claimDeficiencies);
360	                details.put("claimReviewers", claimReviewers);
361	                details.put("duplicateArtifacts", duplicateArtifacts);
362	                details.put("missingArtifacts", missingArtifacts);
363	                throw ApiException.unprocessable("裁决条件不满足", details);
364	            }
365	
366	            // 全部满足：同一事务落定案件并冻结快照，杜绝部分裁决与失效批准冻结。
367	            long newVersion = caseRow.version() + 1;
368	            LocalDateTime decidedAt = now();
369	            caseRepository.markDecided(caseRow.id(), decidedAt);
370	            decisionRepository.insertDecision(caseRow.id(), newVersion, requestId, decidedAt);
371	
372	            List<FrozenClaimView> claimViews = new ArrayList<>();
373	            int claimOrdinal = 0;
374	            for (String key : selectedKeys) {
375	                ClaimRow claim = claimByKey.get(key);
376	                decisionRepository.insertFrozenClaim(caseRow.id(), claim.id(), claim.claimKey(),
377	                        claim.applicant(), claim.statement(), claimOrdinal);
378	                claimViews.add(new FrozenClaimView(claim.claimKey(), claim.applicant(), claim.statement()));
379	                claimOrdinal++;
380	            }
381	
382	            // 藏品按案件清单顺序冻结到唯一选定主张的申请人。
383	            List<FrozenArtifactView> artifactViews = new ArrayList<>();
384	            int artifactOrdinal = 0;
385	            for (String no : caseArtifacts) {
386	                String ownerKey = coveredBy.get(no).get(0);
387	                ClaimRow owner = claimByKey.get(ownerKey);
388	                decisionRepository.insertFrozenArtifact(caseRow.id(), no, owner.id(),
389	                        owner.applicant(), artifactOrdinal);
390	                artifactViews.add(new FrozenArtifactView(no, owner.claimKey(), owner.applicant()));
391	                artifactOrdinal++;
392	            }
393	
394	            List<EvidenceRow> activeEvidence =
395	                    evidenceRepository.findActiveForClaims(new ArrayList<>(claimByKey.values().stream()
396	                            .map(ClaimRow::id).toList()));
397	            List<FrozenEvidenceView> evidenceViews = new ArrayList<>();
398	            int evidenceOrdinal = 0;
399	            for (String key : selectedKeys) {
400	                ClaimRow claim = claimByKey.get(key);
401	                for (EvidenceRow evidence : activeEvidence) {
402	                    if (evidence.claimId() != claim.id()) {
403	                        continue;
404	                    }
405	                    decisionRepository.insertFrozenEvidence(caseRow.id(), claim.id(), evidence.id(),
406	                            evidence.evidenceKey(), evidence.summary(), claim.evidenceVersion(), evidenceOrdinal);
407	                    evidenceViews.add(new FrozenEvidenceView(claim.claimKey(), evidence.evidenceKey(),
408	                            evidence.summary(), claim.evidenceVersion()));
409	                    evidenceOrdinal++;
410	                }
411	            }
412	
413	            List<ApprovalRow> currentApprovals =
414	                    approvalRepository.findCurrentForClaims(new ArrayList<>(claimByKey.values()));
415	            List<FrozenApprovalView> approvalViews = new ArrayList<>();
416	            int approvalOrdinal = 0;
417	            for (String key : selectedKeys) {
418	                ClaimRow claim = claimByKey.get(key);
419	                for (ApprovalRow approval : currentApprovals) {
420	                    if (approval.claimId() != claim.id()) {
421	                        continue;
422	                    }
423	                    decisionRepository.insertFrozenApproval(caseRow.id(), claim.id(), approval.reviewer(),
424	                            approval.evidenceVersion(), approvalOrdinal);
425	                    approvalViews.add(new FrozenApprovalView(claim.claimKey(), approval.reviewer(),
426	                            approval.evidenceVersion()));
427	                    approvalOrdinal++;
428	                }
429	            }
430	
431	            return new DecisionResponse(caseRow.caseKey(), CaseStatus.DECIDED.name(), newVersion,
432	                    claimViews, artifactViews, evidenceViews, approvalViews);
433	        });
434	    }
