436	    @Transactional(readOnly = true)
437	    public DecisionResponse getDecision(String caseKey) {
438	        CaseRow caseRow = requireCase(caseKey);
439	        DecisionRepository.FrozenDecisionHeader header = decisionRepository.findHeader(caseRow.id());
440	        if (header == null) {
441	            throw ApiException.notFound("案件尚无裁决: " + caseKey);
442	        }
443	        List<DecisionRepository.FrozenClaimSnapshot> frozenClaims =
444	                decisionRepository.findClaims(caseRow.id());
445	        Map<Long, String> claimKeyById = new LinkedHashMap<>();
446	        List<FrozenClaimView> claimViews = new ArrayList<>();
447	        for (DecisionRepository.FrozenClaimSnapshot c : frozenClaims) {
448	            claimKeyById.put(c.claimId(), c.claimKey());
449	            claimViews.add(new FrozenClaimView(c.claimKey(), c.applicant(), c.statement()));
450	        }
451	        List<FrozenArtifactView> artifactViews = decisionRepository.findArtifacts(caseRow.id()).stream()
452	                .map(a -> new FrozenArtifactView(a.artifactNo(),
453	                        claimKeyById.getOrDefault(a.claimId(), null), a.applicant()))
454	                .toList();
455	        List<FrozenEvidenceView> evidenceViews = decisionRepository.findEvidence(caseRow.id()).stream()
456	                .map(e -> new FrozenEvidenceView(claimKeyById.get(e.claimId()), e.evidenceKey(),
457	                        e.summary(), e.evidenceVersion()))
458	                .toList();
459	        List<FrozenApprovalView> approvalViews = decisionRepository.findApprovals(caseRow.id()).stream()
460	                .map(a -> new FrozenApprovalView(claimKeyById.get(a.claimId()), a.reviewer(),
461	                        a.evidenceVersion()))
462	                .toList();
463	        return new DecisionResponse(caseRow.caseKey(), caseRow.status(), header.version(),
464	                claimViews, artifactViews, evidenceViews, approvalViews);
465	    }
466	
467	    // ---------------------------------------------------------------------
468	    // 幂等与通用校验
469	    // ---------------------------------------------------------------------
470	
471	    /**
472	     * 写操作幂等模板：同键同操作者同参重放首次结果，异操作者或异参 409；
473	     * 业务失败随事务回滚、不占键。
474	     *
475	     * @param successStatus 首次成功的 HTTP 状态码（201 或 204）
476	     */
477	    private <T> T withIdempotency(String requestId, String actorId, String opKey, String fingerprint,
478	                                  int successStatus, java.util.function.Supplier<T> action) {
479	        requireText(actorId, "X-Actor-Id");
480	        requireText(requestId, "X-Request-Id");
481	        RequestRecordRow existing = requestRecordRepository.lock(requestId);
482	        if (existing != null) {
483	            return replayOrConflict(existing, actorId, opKey, fingerprint);
484	        }
485	        try {
486	            requestRecordRepository.tryInsert(requestId, actorId, opKey, fingerprint);
487	        } catch (DuplicateKeyException concurrent) {
488	            // 同键并发：另一事务已插入，阻塞等待其结束后走重放/失败分支。
489	            RequestRecordRow concurrentRow = requestRecordRepository.lock(requestId);
490	            if (concurrentRow == null) {
491	                // 对方失败回滚未占键：当前请求继续首次执行。
492	                requestRecordRepository.tryInsert(requestId, actorId, opKey, fingerprint);
493	            } else {
494	                return replayOrConflict(concurrentRow, actorId, opKey, fingerprint);
495	            }
496	        }
497	        T result;
498	        try {
499	            result = action.get();
500	        } catch (RuntimeException ex) {
501	            // 失败不占键：占位随事务回滚一并清除，同时向上抛出原错误。
502	            requestRecordRepository.release(requestId);
503	            throw ex;
504	        }
505	        String body = result == null ? null : writeJson(result);
506	        requestRecordRepository.complete(requestId, successStatus, body);
507	        return result;
508	    }
509	
510	    /**
511	     * 已存在幂等记录时：同操作者同操作同参重放，否则 409。
512	     * 占位行（http_status=0）只会在持锁事务内出现，此处能读到说明对方已完成。
513	     */
514	    private <T> T replayOrConflict(RequestRecordRow row, String actorId, String opKey, String fingerprint) {
515	        if (!row.actorId().equals(actorId) || !row.opKey().equals(opKey)
516	                || !row.fingerprint().equals(fingerprint)) {
517	            throw ApiException.conflict("idempotency_conflict",
518	                    "requestId 已被不同操作者或不同参数占用");
519	        }
520	        if (row.httpStatus() == 0) {
521	            // 极端情况下读到未完成占位：视为并发冲突，调用方按版本冲突语义重试。
522	            throw ApiException.conflict("request_in_flight", "相同 requestId 的请求仍在处理中");
523	        }
524	        throw new IdempotentReplayException(row.httpStatus(), row.responseBody());
525	    }
526	
527	    private CaseRow requireCase(String caseKey) {
528	        requireText(caseKey, "caseKey");
529	        CaseRow caseRow = caseRepository.findByKey(caseKey);
530	        if (caseRow == null) {
531	            throw ApiException.notFound("案件不存在: " + caseKey);
532	        }
533	        return caseRow;
534	    }
535	
536	    private CaseRow lockOpenCase(String caseKey) {
537	        requireText(caseKey, "caseKey");
538	        CaseRow caseRow = caseRepository.lockByKey(caseKey);
539	        if (caseRow == null) {
540	            throw ApiException.notFound("案件不存在: " + caseKey);
541	        }
542	        if (CaseStatus.DECIDED.name().equals(caseRow.status())) {
543	            throw ApiException.conflict("case_decided", "案件已裁决终态，拒绝新写入");
544	        }
545	        return caseRow;
546	    }
547	
548	    private List<String> normalizeArtifactList(List<String> input, boolean rejectDuplicates) {
549	        if (input == null || input.isEmpty()) {
550	            throw ApiException.badRequest("藏品编号列表不能为空");
551	        }
552	        if (input.size() > MAX_ARTIFACTS) {
553	            throw ApiException.badRequest("藏品编号至多 " + MAX_ARTIFACTS + " 个");
554	        }
555	        List<String> result = new ArrayList<>();
556	        for (String no : input) {
557	            if (no == null || no.isBlank()) {
558	                throw ApiException.badRequest("藏品编号不能为空");
559	            }
560	            String trimmed = no.trim();
561	            if (rejectDuplicates && result.contains(trimmed)) {
562	                throw ApiException.badRequest("藏品编号重复: " + trimmed);
563	            }
564	            result.add(trimmed);
565	        }
566	        return result;
567	    }
568	
569	    private void requireText(String value, String field) {
570	        if (value == null || value.isBlank()) {
571	            throw ApiException.badRequest(field + " 不能为空");
572	        }
573	    }
574	
575	    private LocalDateTime now() {
576	        return LocalDateTime.now(clock);
577	    }
578	
579	    private String writeJson(Object value) {
580	        try {
581	            return objectMapper.writeValueAsString(value);
582	        } catch (JsonProcessingException e) {
583	            throw new IllegalStateException("响应序列化失败", e);
584	        }
585	    }
586	
587	    /**
588	     * 规范化参数指纹：Map 键排序、集合排序，集合换序视为同参。
589	     */
590	    private String fingerprint(Map<String, ?> params) {
591	        try {
592	            return objectMapper.writeValueAsString(new TreeMap<>(params));
593	        } catch (JsonProcessingException e) {
594	            throw new IllegalStateException("参数指纹生成失败", e);
595	        }
596	    }
597	
598	    private CaseResponse buildCaseResponse(CaseRow caseRow) {
599	        return new CaseResponse(
600	                caseRow.caseKey(),
601	                caseRow.status(),
602	                caseRow.version(),
603	                caseRepository.findArtifactNos(caseRow.id()));
604	    }
605	
606	    private ClaimResponse buildClaimResponse(ClaimRow claim) {
607	        return new ClaimResponse(
608	                claim.claimKey(),
609	                claim.applicant(),
610	                claim.statement(),
611	                claim.status(),
612	                claim.evidenceVersion(),
613	                claimRepository.findClaimArtifactNos(claim.id()),
614	                approvalRepository.findReviewersAtVersion(claim.id(), claim.evidenceVersion()));
615	    }
616	
617	    /**
618	     * 裁决选定主张键规范化：1至10个、非空、彼此不同（非法为 400）；保留提交顺序。
619	     */
620	    private List<String> normalizeSelectedClaimKeys(List<String> input) {
621	        if (input == null || input.isEmpty()) {
622	            throw ApiException.badRequest("至少选定一个主张");
623	        }
624	        if (input.size() > MAX_ARTIFACTS) {
625	            throw ApiException.badRequest("至多选定 " + MAX_ARTIFACTS + " 个主张");
626	        }
627	        List<String> result = new ArrayList<>();
628	        for (String key : input) {
629	            if (key == null || key.isBlank()) {
630	                throw ApiException.badRequest("claimKey 不能为空");
631	            }
632	            String trimmed = key.trim();
633	            if (result.contains(trimmed)) {
634	                throw ApiException.badRequest("选定主张不能重复: " + trimmed);
635	            }
636	            result.add(trimmed);
637	        }
638	        return result;
639	    }
640	
641	    private List<String> sortedCopy(List<String> input) {
642	        List<String> copy = new ArrayList<>(input);
643	        java.util.Collections.sort(copy);
644	        return copy;
645	    }
646	
647	    /**
648	     * 取有效主张：不存在 404，已撤回 409。
649	     */
650	    private ClaimRow requireActiveClaim(CaseRow caseRow, String claimKey) {
651	        ClaimRow claim = claimRepository.findByKey(caseRow.id(), claimKey);
652	        if (claim == null) {
653	            throw ApiException.notFound("主张不存在: " + claimKey);
654	        }
655	        ensureClaimNotWithdrawn(claim);
656	        return claim;
657	    }
658	
659	    private void ensureClaimNotWithdrawn(ClaimRow claim) {
660	        if (com.example.starter.restitution.domain.ClaimStatus.WITHDRAWN.name().equals(claim.status())) {
661	            throw ApiException.conflict("claim_withdrawn", "主张已撤回，不可写入证据或批准");
662	        }
663	    }
664	
665	    private EvidenceResponse buildEvidenceResponse(EvidenceRow evidence, long evidenceVersion) {
666	        return new EvidenceResponse(
667	                evidence.evidenceKey(),
668	                evidence.summary(),
669	                evidence.status(),
670	                evidenceVersion);
671	    }
672	}
