        approve(c, "CL-1", "r1");
        assertThat(currentVersion(c)).isEqualTo(beforeApproval + 1);

        // 同一人同版本重复批准：不重复计数，不再加版本。
        approve(c, "CL-1", "r1");
        assertThat(currentVersion(c)).isEqualTo(beforeApproval + 1);

